#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

cd "$(dirname "$0")/.."
DOMAIN="crownd.dev"
SITE="https://$DOMAIN"
WR="npx --yes wrangler"
SECRETS=".secrets.production"   # Stripe + internal secrets: gitignored, never read by Next.js
PUBLIC=".env.production"        # public build config: verification meta codes (printed in the HTML anyway)
ENV_FILE="$SECRETS"

banner "Crownd · Go-live: pagamentos + buscadores"

collapse_double() {
  local v="$1" h=$(( ${#1} / 2 ))
  if (( ${#v} % 2 == 0 && h > 0 )) && [[ "${v:0:h}" == "${v:h}" ]]; then printf '%s' "${v:0:h}"; else printf '%s' "$v"; fi
}
health() { curl -s --max-time 15 "$SITE/api/health"; }

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Stripe: chave LIVE"
say "Sua conta Stripe já está ativada (cobranças e saques liberados). Falta só a chave LIVE."
open_url "https://dashboard.stripe.com/apikeys"
step "Confira que o seletor no topo NÃO está em 'Test mode' / 'Ambiente de teste'."
step "Na linha 'Secret key' / 'Chave secreta', clique em 'Reveal live key' / 'Revelar' e copie (começa com sk_live_)."
note "A chave não aparece na tela nem vai para o código: fica em $SECRETS (ignorado pelo git) e no cofre da Cloudflare."
while true; do
  ask_secret STRIPE_LIVE_SECRET_KEY "Cole a chave LIVE uma única vez (fica oculta):" || { warn "Sem entrada."; finish; return; }
  STRIPE_LIVE_SECRET_KEY=$(collapse_double "$STRIPE_LIVE_SECRET_KEY")
  if [[ ! "$STRIPE_LIVE_SECRET_KEY" =~ ^(sk|rk)_live_ ]]; then warn "Esperado sk_live_… (essa parece ser de teste ou de outro tipo)."; continue; fi
  if curl -s -u "$STRIPE_LIVE_SECRET_KEY:" https://api.stripe.com/v1/balance | grep -q '"error"'; then
    warn "O Stripe recusou essa chave. Copie de novo."
    continue
  fi
  note "Chave LIVE aceita pelo Stripe."
  break
done
write_env STRIPE_LIVE_SECRET_KEY "$STRIPE_LIVE_SECRET_KEY"
pause "Enter para ligar os pagamentos"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Stripe: webhook e pagamentos em produção"
WHSEC=$(_existing STRIPE_WEBHOOK_SECRET || true)
if [[ "$WHSEC" =~ ^whsec_ ]] && confirm "Já existe um STRIPE_WEBHOOK_SECRET salvo. Reaproveitar?"; then
  note "Reaproveitando o segredo do webhook."
else
  say "Criando o endpoint $SITE/api/webhooks/stripe pela API do Stripe (modo LIVE)…"
  STRIPE_SECRET_KEY="$STRIPE_LIVE_SECRET_KEY" node --use-system-ca --disable-warning=MODULE_TYPELESS_PACKAGE_JSON \
    scripts/stripe-webhook.mts --url "$SITE" --env-file "$SECRETS" --recreate || warn "Falha ao criar o webhook."
  WHSEC=$(_existing STRIPE_WEBHOOK_SECRET || true)
fi
if [[ ! "$WHSEC" =~ ^whsec_ ]]; then
  warn "Sem segredo do webhook: os pagamentos não seriam confirmados. Rode de novo: npm.cmd run golive"
  finish; return
fi
say "Enviando a chave e o segredo para o cofre da Cloudflare…"
SECRETS_JSON=$(mktemp)
# Values travel via environment variables, never argv (other processes can read argv).
K="$STRIPE_LIVE_SECRET_KEY" W="$WHSEC" \
  node -e 'process.stdout.write(JSON.stringify({STRIPE_SECRET_KEY: process.env.K, STRIPE_WEBHOOK_SECRET: process.env.W}))' > "$SECRETS_JSON"
if ! $WR secret bulk "$SECRETS_JSON"; then
  rm -f "$SECRETS_JSON"
  warn "A Cloudflare recusou os segredos (login expirado?). Rode: npm.cmd run cf:login e depois npm.cmd run golive"
  finish; return
fi
rm -f "$SECRETS_JSON"
say "Conferindo em produção…"
for _ in $(seq 1 12); do health | grep -q '"payments":"stripe"' && break; sleep 5; done
if health | grep -q '"payments":"stripe".*"webhook":true'; then
  note "✓ Lances ABERTOS em $SITE (Stripe LIVE + webhook)."
else
  warn "Produção ainda não mostra pagamentos abertos: $(health)"
  SKIPPED+=("Conferir $SITE/api/health → payments: stripe, webhook: true")
fi
pause "Enter para continuar"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Stripe: Pix (opcional, recomendado no Brasil)"
say "Hoje a conta aceita cartão e boleto. O Pix precisa ser ativado no painel."
if confirm "Quer ativar o Pix agora?"; then
  open_url "https://dashboard.stripe.com/settings/payment_methods"
  step "Em 'Payment methods' / 'Formas de pagamento', procure 'Pix' e clique em 'Turn on' / 'Ativar' (ou 'Request access')."
  step "Se pedir aprovação, o Stripe avisa por e-mail. Nada mais muda no código: o Checkout passa a mostrar o Pix sozinho."
  pause "Enter quando terminar"
else
  SKIPPED+=("Ativar o Pix em dashboard.stripe.com/settings/payment_methods")
fi
note "Dica: em Settings → Public details, coloque o site $SITE e o suporte. Aparece no Checkout e reduz contestações."
pause "Enter para continuar"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google Search Console"
open_url "https://search.google.com/search-console/welcome"
step "Escolha o tipo 'Domínio' (à esquerda), digite $DOMAIN e clique em 'Continuar'."
step "O Google detecta a Cloudflare: clique em 'Iniciar verificação', entre na Cloudflare e autorize. Pronto."
note "Se ele mostrar só um registro TXT: copie-o, abra dash.cloudflare.com → $DOMAIN → DNS → Add record → Type TXT, Name @, cole e salve. Volte e clique em 'Verificar'."
pause "Enter quando a propriedade estiver verificada"
step "No menu 'Sitemaps', digite sitemap.xml e clique em 'Enviar'."
step "Em 'Inspeção de URL', cole $SITE/br e clique em 'Solicitar indexação'. Repita para $SITE e $SITE/us."
pause "Enter para continuar"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Bing Webmaster Tools (alimenta também o Copilot e a busca do ChatGPT)"
open_url "https://www.bing.com/webmasters"
step "Entre com sua conta Microsoft ou Google."
step "Escolha 'Import from Google Search Console' / 'Importar do GSC', autorize e importe $DOMAIN (o sitemap vem junto)."
note "O Crownd já avisa o Bing via IndexNow a cada mudança de #1."
pause "Enter quando o site aparecer no Bing"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Naver Search Advisor (Coreia)"
ENV_FILE="$PUBLIC"
open_url "https://searchadvisor.naver.com/console/board"
step "Entre (dá para criar conta Naver com e-mail). Em 'Site management' / '사이트 관리', adicione $SITE."
step "Escolha 'HTML tag' / 'HTML 태그'. Copie SÓ o valor de content=\"…\" (não a tag inteira)."
note "Não clique em 'Verify' ainda: a tag entra no ar na etapa 8."
ask NEXT_PUBLIC_NAVER_SITE_VERIFICATION "Cole o código do Naver (Enter vazio para pular):" || true
NEXT_PUBLIC_NAVER_SITE_VERIFICATION=$(printf '%s' "$NEXT_PUBLIC_NAVER_SITE_VERIFICATION" | sed -E 's/.*content="([^"]+)".*/\1/')
if [[ -n "$NEXT_PUBLIC_NAVER_SITE_VERIFICATION" ]]; then
  write_env NEXT_PUBLIC_NAVER_SITE_VERIFICATION "$NEXT_PUBLIC_NAVER_SITE_VERIFICATION"
else
  SKIPPED+=("Naver Search Advisor: rodar npm.cmd run golive de novo quando tiver a conta")
fi
pause "Enter para continuar"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Yandex Webmaster (forte na Turquia)"
open_url "https://webmaster.yandex.com/sites/add/"
step "Entre (conta Yandex ou Google), adicione $SITE e escolha 'Meta tag'."
step "Copie SÓ o valor de content=\"…\"."
ask NEXT_PUBLIC_YANDEX_SITE_VERIFICATION "Cole o código do Yandex (Enter vazio para pular):" || true
NEXT_PUBLIC_YANDEX_SITE_VERIFICATION=$(printf '%s' "$NEXT_PUBLIC_YANDEX_SITE_VERIFICATION" | sed -E 's/.*content="([^"]+)".*/\1/')
if [[ -n "$NEXT_PUBLIC_YANDEX_SITE_VERIFICATION" ]]; then
  write_env NEXT_PUBLIC_YANDEX_SITE_VERIFICATION "$NEXT_PUBLIC_YANDEX_SITE_VERIFICATION"
else
  SKIPPED+=("Yandex Webmaster: opcional")
fi
pause "Enter para continuar"
ENV_FILE="$SECRETS"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Publicar as tags e confirmar"
if [[ -n "${NEXT_PUBLIC_NAVER_SITE_VERIFICATION:-}${NEXT_PUBLIC_YANDEX_SITE_VERIFICATION:-}" ]]; then
  say "Publicando o site com as tags de verificação (cerca de 5 minutos)…"
  if npm run deploy; then
    note "Publicado."
    if [[ -n "${NEXT_PUBLIC_NAVER_SITE_VERIFICATION:-}" ]]; then
      step "Naver: clique em 'Verify' / '소유확인'. Depois: 요청 → 사이트맵 제출 → $SITE/sitemap.xml"
      step "Naver: 요청 → RSS 제출 → $SITE/kr/feed.xml"
    fi
    [[ -n "${NEXT_PUBLIC_YANDEX_SITE_VERIFICATION:-}" ]] && step "Yandex: clique em 'Check'. Depois: Indexing → Sitemap files → $SITE/sitemap.xml"
    pause "Enter quando terminar"
  else
    warn "O deploy falhou: veja o erro acima. Rode depois: npm.cmd run deploy"
  fi
else
  note "Nenhum código novo: nada a publicar."
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "IndexNow e auditoria final"
say "Avisando Bing, Yandex, Naver, Seznam e Yep de todas as páginas…"
npm run --silent indexnow || warn "IndexNow falhou: veja acima."
say "Auditando o SEO de todas as páginas em produção…"
npm run --silent seo:check -- --base "$SITE" || warn "A auditoria apontou itens: veja acima."
note "Status dos pagamentos: $(health)"
open_url "$SITE/br"
pause "Enter para finalizar"

finish
}

run_wizard "$@"; exit
